// Retrieve the YAML channels data from the flow context
var channels = flow.get('ConfigChannels') || {};
var action = msg.payload; // This will be true (on) or false (off) from the switch

// Function to convert LV channel numbers
function convertLvChannel(channel) {
    switch(channel) {
        case 0: return 3;
        case 3: return 0;
        case 1: return 2;
        case 2: return 1;
        case 4: return 7;
        case 7: return 4;
        case 5: return 6;
        case 6: return 5;
        default: return channel; // No conversion for other channels
    }
}

// Function to send a command with a delay
function sendWithDelay(topic, payload, delay) {
    setTimeout(function() {
        msg.topic = topic;
        msg.payload = payload;
        node.send(msg);
    }, delay * 1000); // Convert seconds to milliseconds
}

// Function to process HV or LV channels
function processChannels(channels, processHvFirst) {
    var channelIds = Object.keys(channels);

    // Sort channels by board and channel for consistent order
    channelIds.sort(function(a, b) {
        var aBoard = channels[a].board;
        var bBoard = channels[b].board;
        var aChannel = channels[a].chan;
        var bChannel = channels[b].chan;
        if (aBoard !== bBoard) return aBoard - bBoard;
        return aChannel - bChannel;
    });

    // Process HV and LV channels in the correct order
    for (var i = 0; i < channelIds.length; i++) {
        var channel_id = channelIds[i];
        var channel_cfg = channels[channel_id];
        var hv_cfg = channel_cfg.hv;
        var lv_cfg = channel_cfg.lv;

        if (processHvFirst) {
            // Turn HV channel on or off
            sendWithDelay(
                `/SY4527/cmd/switch/${hv_cfg.board}/${hv_cfg.chan}`,
                action ? "on" : "off",
                0
            );
        } else {
            // Turn LV channel on or off (apply conversion)
            var convertedChannel = convertLvChannel(lv_cfg.chan);
            sendWithDelay(
                `/SY4527/cmd/switch/${lv_cfg.board}/${convertedChannel}`,
                action ? "on" : "off",
                0
            );
        }
    }
}

// Process LV channels first if powering on, or HV channels first if powering off
if (action) {
    // Powering ON: LV first, then HV
    processChannels(channels, false);
    setTimeout(function() {
        processChannels(channels, true);
    }, 10000); // 10-second delay after LV
} else {
    // Powering OFF: HV first, then LV
    processChannels(channels, true);
    setTimeout(function() {
        processChannels(channels, false);
    }, 10000); // 10-second delay after HV
}

return;

