var input = msg.payload
var channel_stat = []
var slotNumber = flow.get("slotNumber"); // Default to slot 1 if not set
//node.warn("Current slotNumber:" + slotNumber);
// Calculate the start and end indices for the loop
var startIndex = parseInt(slotNumber) * 12;
var endIndex = (parseInt(slotNumber) + 1) * 12;


for (let index = startIndex; index < endIndex; index++) { 
    // input.length
    if (!input[index]) {
        node.warn(`Input at index ${index} is undefined. Skipping.`);
        continue; // Skip this iteration
    }
    var element = input[index].on;
    var stat = input[index].status;
    if (stat == 256) {
        channel_stat.push({payload : "INTLCK",
        background: "red"});
    }
    else if (stat == 64) {
        channel_stat.push({payload : "EXT TRP",
        background: "red"});
    }
    else if (stat ==512) {
        channel_stat.push({payload : "INT TRP",
        background: "red"});
    }
    else if (stat >= 8) {
        channel_stat.push({payload : "ALM",
        background: "red"});
    }
    else if (stat == 3) {
        channel_stat.push({payload : "RUp",
        background: "orange"});
    }
    else if (stat == 5) {
        channel_stat.push({payload : "RDn",
        background: "orange"});
    }
    else if (stat == 1){
        channel_stat.push({payload :"ON", 
        background: "green"
        });
    }
    else {
        channel_stat.push({payload : "OFF",
        background: "grey"});
    };

    //channel_stat.push({payload: element.on, background: 'green'});
}

